(function(){
 const canvas=document.querySelector('#layered-map');if(!canvas||!window.L)return;
 const bounds=[[51.525,-.235],[51.621,-.055]];
 const map=L.map(canvas,{scrollWheelZoom:false,zoomControl:false,attributionControl:false,minZoom:11,maxZoom:17,maxBounds:[[51.51,-.255],[51.635,-.035]],maxBoundsViscosity:.85});
 L.control.zoom({position:'bottomright'}).addTo(map);
 const street=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Esri World Street Map'});
 const topo=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Esri World Topographic'});
 const bases={street,topo};let activeBase='topo',tileErrors=0;
 topo.addTo(map);map.setView([51.57,-.15],13);
 topo.on('tileerror',()=>{tileErrors+=1;if(tileErrors===4){const status=document.querySelector('#map-source-status');if(status)status.textContent='Basemap temporarily unavailable'}});
 map.createPane('corridorPane');map.getPane('corridorPane').style.zIndex=360;
 map.createPane('routePane');map.getPane('routePane').style.zIndex=365;
 map.createPane('labelPane');map.getPane('labelPane').style.zIndex=610;map.getPane('labelPane').style.pointerEvents='none';
 const zones=L.layerGroup();
 const ovalZones={1:{centre:[51.584,-.209],rx:1150,ry:2550,rotation:18},2:{centre:[51.593,-.160],rx:1050,ry:2450,rotation:4},3:{centre:[51.586,-.112],rx:1200,ry:2500,rotation:-42},4:{centre:[51.561,-.095],rx:1150,ry:2400,rotation:-52},5:{centre:[51.543,-.154],rx:950,ry:2250,rotation:2},6:{centre:[51.543,-.203],rx:1100,ry:2350,rotation:-26}};
 function ellipsePoints(shape){const points=[],lat=shape.centre[0],lng=shape.centre[1],angle=shape.rotation*Math.PI/180,cosA=Math.cos(angle),sinA=Math.sin(angle);for(let i=0;i<64;i++){const t=i/64*Math.PI*2,x=shape.rx*Math.cos(t),y=shape.ry*Math.sin(t),east=x*cosA-y*sinA,north=x*sinA+y*cosA;points.push([lat+north/111320,lng+east/(111320*Math.cos(lat*Math.PI/180))])}return points}
 (window.NNL_ZONES||[]).forEach(zone=>{const geometry=ovalZones[zone.id];const oval=L.polygon(ellipsePoints(geometry),{pane:'corridorPane',className:'nnl-zone-shape',color:'#d839c7',weight:2.5,opacity:.84,fillColor:'#e75ad8',fillOpacity:.09,smoothFactor:1});oval.bindPopup(`<div class="map-popup"><small>Nature corridor ${zone.id}</small><h3>${zone.name}</h3><p>${zone.places}</p><em>Indicative oval working area. Final boundaries will be checked with network members.</em></div>`).addTo(zones);L.marker(geometry.centre,{pane:'labelPane',interactive:false,icon:L.divIcon({className:'corridor-number-wrap',html:`<span class="corridor-number">${zone.id}</span>`,iconSize:[38,38],iconAnchor:[19,19]})}).addTo(zones)});zones.addTo(map);
 const routeData=[[[51.561,-.169],[51.575,-.185],[51.593,-.210],[51.605,-.228]],[[51.566,-.162],[51.580,-.155],[51.601,-.163],[51.619,-.170]],[[51.566,-.151],[51.582,-.132],[51.594,-.105],[51.604,-.079]],[[51.557,-.146],[51.565,-.122],[51.570,-.096],[51.558,-.070]],[[51.553,-.158],[51.540,-.153],[51.526,-.153]],[[51.552,-.174],[51.540,-.195],[51.526,-.216]]];
 const links=L.layerGroup();routeData.forEach((coords,index)=>L.polyline(coords,{pane:'routePane',className:'habitat-link',color:'#2b8a55',weight:4,opacity:.88,dashArray:'2 10',lineCap:'round'}).bindTooltip(`Habitat connection ${index+1}`,{sticky:true}).addTo(links));links.addTo(map);
 const members=L.layerGroup();(window.NNL_PROJECTS||[]).forEach((project,index)=>{const icon=L.divIcon({className:'project-pin-wrap',html:`<span class="project-pin"><b>${index+1}</b></span>`,iconSize:[38,38],iconAnchor:[19,36]});L.marker([project.lat,project.lng],{icon}).bindTooltip(project.name,{direction:'top',offset:[0,-28],className:'project-tooltip'}).bindPopup(`<div class="map-popup"><small>${project.borough} · ${project.type}</small><h3>${project.name}</h3><p>${project.summary}</p><em>${project.status}</em></div>`).on('click',()=>{if(typeof window.selectProject==='function')window.selectProject(project.id)}).addTo(members)});members.addTo(map);
 const initiatives=L.layerGroup();(window.NNL_OTHER_INITIATIVES||[]).forEach(item=>{L.circleMarker([item.lat,item.lng],{radius:9,color:'#fffdf6',weight:3,fillColor:'#f2b632',fillOpacity:1}).bindTooltip(item.name,{direction:'top',className:'project-tooltip'}).bindPopup(`<div class="map-popup"><small>${item.kind}</small><h3>${item.name}</h3><p>${item.note}</p></div>`).addTo(initiatives)});
 function setBase(name){if(!bases[name]||name===activeBase)return;Object.values(bases).forEach(layer=>map.removeLayer(layer));bases[name].addTo(map);activeBase=name;document.querySelectorAll('[data-map-base]').forEach(button=>button.classList.toggle('active',button.dataset.mapBase===name));const status=document.querySelector('#map-source-status');if(status)status.textContent='Live accurate basemap'}
 function toggleLayer(name,on){const layers={zones,links,members,initiatives};if(!layers[name])return;if(on)layers[name].addTo(map);else map.removeLayer(layers[name])}
 const panel=L.control({position:'topright'});panel.onAdd=()=>{const div=L.DomUtil.create('section','nnl-layer-panel');div.innerHTML=`<div class="map-panel-heading"><span>Explore the network</span><small id="map-source-status">Live accurate basemap</small></div><div class="map-style-switch" aria-label="Choose map style"><button data-map-base="street">Streets</button><button class="active" data-map-base="topo">Terrain</button></div><fieldset><legend>Accurate data layers</legend><label><input type="checkbox" data-map-layer="zones" checked><i class="key-zone"></i>Six NNL corridors</label><label><input type="checkbox" data-map-layer="links" checked><i class="key-link"></i>Habitat connections</label><label><input type="checkbox" data-map-layer="members" checked><i class="key-project"></i>Member projects</label><label><input type="checkbox" data-map-layer="initiatives"><i class="key-initiative"></i>Other initiatives</label></fieldset><p class="map-panel-note">The basemap remains geographically accurate; colour and corridor styling are separate overlays.</p>`;L.DomEvent.disableClickPropagation(div);L.DomEvent.disableScrollPropagation(div);return div};panel.addTo(map);
 document.querySelectorAll('[data-map-base]').forEach(button=>button.addEventListener('click',()=>setBase(button.dataset.mapBase)));
 document.querySelectorAll('[data-map-layer]').forEach(input=>input.addEventListener('change',()=>toggleLayer(input.dataset.mapLayer,input.checked)));
 L.control.scale({imperial:false,position:'bottomleft'}).addTo(map);setTimeout(()=>map.invalidateSize(),120);
})();
